  room_id int,
  slot    tsrange,
  EXCLUDE USING gist (room_id WITH =, slot WITH &&)
);

-- Deferrable FK, checked at COMMIT
FOREIGN KEY (session_id) REFERENCES sessions(id)
  DEFERRABLE INITIALLY DEFERRED;

